<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$msg=null;$rows=[];
try{$pdo=business_db();comm_step21_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$s=$pdo->prepare("UPDATE communication_rules SET in_app_enabled=?,email_enabled=?,whatsapp_enabled=?,sms_enabled=?,auto_external=?,is_active=? WHERE organization_id=? AND id=?");$s->execute([!empty($_POST['in_app_enabled'])?1:0,!empty($_POST['email_enabled'])?1:0,!empty($_POST['whatsapp_enabled'])?1:0,!empty($_POST['sms_enabled'])?1:0,!empty($_POST['auto_external'])?1:0,!empty($_POST['is_active'])?1:0,$orgId,$id]);$msg='Communication rule updated.';}$s=$pdo->prepare("SELECT * FROM communication_rules WHERE organization_id=? ORDER BY category,rule_name");$s->execute([$orgId]);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Communication Rules - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="communication_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Notification Rules</small></span></a><div class="os-top-actions"><a class="os-btn" href="communication_settings.php">Channels</a><a class="os-btn primary" href="communication_center.php">Communications</a></div></div></header><main class="os-main" style="max-width:1320px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">STEP 21 • AUTOMATION RULES</div><h1>Control which operational events become notifications.</h1><p>In-app is enabled by default. External auto-delivery is off by default and should only be enabled after the relevant channel/provider and user preferences are ready.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><?php if($msg):?><div class="pp-alert good"><?=comm_step21_h($msg)?></div><?php endif;?><section class="os-card" style="margin-top:14px"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Rule</th><th>Audience</th><th>Severity</th><th>Channels</th><th>Automation</th><th>Save</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><td><b><?=comm_step21_h($r['rule_name'])?></b><br><small><?=comm_step21_h($r['event_type'])?> • <?=comm_step21_h($r['rule_code'])?></small></td><td><?=comm_step21_h($r['audience_permission'])?></td><td><span class="pp-badge <?=in_array($r['severity'],['critical','high'],true)?'warn':''?>"><?=comm_step21_h(strtoupper((string)$r['severity']))?></span></td><td><label><input type="checkbox" name="in_app_enabled" value="1" <?=((int)$r['in_app_enabled']===1)?'checked':''?>> In-App</label><br><label><input type="checkbox" name="email_enabled" value="1" <?=((int)$r['email_enabled']===1)?'checked':''?>> Email</label><br><label><input type="checkbox" name="whatsapp_enabled" value="1" <?=((int)$r['whatsapp_enabled']===1)?'checked':''?>> WhatsApp</label><br><label><input type="checkbox" name="sms_enabled" value="1" <?=((int)$r['sms_enabled']===1)?'checked':''?>> SMS</label></td><td><label><input type="checkbox" name="auto_external" value="1" <?=((int)$r['auto_external']===1)?'checked':''?>> Auto external to permitted internal users</label><br><label><input type="checkbox" name="is_active" value="1" <?=((int)$r['is_active']===1)?'checked':''?>> Rule active</label></td><td><button class="os-btn">Save</button></td></form></tr><?php endforeach;?></tbody></table></div></section><div class="os-footer-note"><strong>Scope:</strong> automatic external rules notify internal Business OS users only. Customer/Supplier outbound messages remain explicit Compose/Outbox actions so private CRM data is not pushed externally without a deliberate action.</div></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
